declare(strict_types=1);require_once dirname(__DIR__).'/src/bootstrap.php';Auth::requireOwner();$id=(int)($_GET['id']??0);AdminUi::header($id?'تقرير عماد':'مراجعات عماد','qa');echo AdminUi::flash();if($id){$q=db()->prepare("SELECT r.*,p.name project_name,p.primary_domain,t.title task_title,a.display_name reviewer FROM reviews r LEFT JOIN projects p ON p.id=r.project_id LEFT JOIN tasks t ON t.id=r.task_id LEFT JOIN agents a ON a.id=r.reviewer_agent_id WHERE r.id=?");$q->execute([$id]);$r=$q->fetch();if(!$r)throw new RuntimeException('review_not_found');$tests=db()->prepare('SELECT * FROM review_tests WHERE review_id=? ORDER BY id');$tests->execute([$id]);$e=json_decode((string)($r['evidence_json']??'{}'),true)?:[];?>
<div class="grid"><section class="card span-8"><div class="card-title"><div><h2><?=e($r['project_name']?:'مراجعة مهمة')?> — <?=e($r['task_title'])?></h2><span class="muted small">المراجع: <?=e($r['reviewer'])?> · <?=e(AdminUi::date($r['created_at']))?></span></div><?=AdminUi::badge($r['status'])?></div><div class="pre"><?=e($r['summary'])?></div><?php if($r['recommendation']):?><div class="subtle" style="margin-top:12px"><b>توصية عماد</b><p><?=e($r['recommendation'])?></p></div><?php endif?></section><section class="card span-4"><div class="card-title"><h2>نتيجة الاختبار</h2></div><dl class="kvs"><dt>نجح</dt><dd class="kpi-good"><?=(int)$r['tests_passed']?></dd><dt>فشل</dt><dd class="kpi-bad"><?=(int)$r['tests_failed']?></dd><dt>ملاحظات</dt><dd class="kpi-warn"><?=(int)$r['warnings']?></dd><dt>المشروع</dt><dd><?=e($r['primary_domain']?:'—')?></dd><dt>المهمة</dt><dd><a class="link" href="tasks.php?id=<?=$r['task_id']?>">#<?=$r['task_id']?></a></dd></dl><form method="post" action="action.php" style="margin-top:14px"><?=AdminUi::csrf()?><input type="hidden" name="action" value="qa_retest"><input type="hidden" name="review_id" value="<?=$id?>"><button class="btn secondary full-width">إعادة اختبار مستقلة</button></form></section>
<section class="card span-12"><div class="card-title"><h2>الاختبارات اللي اتعملت</h2></div><div class="table-wrap"><table><thead><tr><th>النوع</th><th>الاختبار</th><th>المتوقع</th><th>الفعلي</th><th>الحالة</th></tr></thead><tbody><?php foreach($tests->fetchAll() as $t):?><tr><td><?=e(AdminUi::label((string)$t['test_type']))?></td><td><?=e($t['test_name'])?></td><td><?=e($t['expected']?:'—')?></td><td><?=e($t['actual']?:'—')?></td><td><?=AdminUi::badge($t['status'])?></td></tr><?php endforeach?></tbody></table></div></section><?php if($e):?><section class="card span-12"><div class="card-title"><h2>الأدلة والسجلات</h2></div><div class="pre mono"><?=e(json_encode($e,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES))?></div></section><?php endif?></div>
<?php }else{$rows=db()->query("SELECT r.*,p.name project_name,t.title task_title,a.display_name reviewer FROM reviews r LEFT JOIN projects p ON p.id=r.project_id LEFT JOIN tasks t ON t.id=r.task_id LEFT JOIN agents a ON a.id=r.reviewer_agent_id ORDER BY r.id DESC LIMIT 250")->fetchAll();?><section class="card"><div class="card-title"><div><h2>تقارير مراجعة عماد والتسليم</h2><span class="muted small">لا تعتبر المهمة مكتملة إلا بعد مراجعة فعلية وأدلة.</span></div></div><div class="table-wrap"><table><thead><tr><th>#</th><th>المشروع</th><th>المهمة</th><th>المراجع</th><th>نجح</th><th>فشل</th><th>ملاحظات</th><th>الحالة</th><th>التاريخ</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><a href="qa.php?id=<?=$r['id']?>">#<?=$r['id']?></a></td><td><?=e($r['project_name']?:'—')?></td><td><?=e($r['task_title'])?></td><td><?=e($r['reviewer'])?></td><td><?=(int)$r['tests_passed']?></td><td><?=(int)$r['tests_failed']?></td><td><?=(int)$r['warnings']?></td><td><?=AdminUi::badge($r['status'])?></td><td><?=e(AdminUi::date($r['created_at']))?></td></tr><?php endforeach?></tbody></table></div></section><?php }AdminUi::footer();
